import assert from 'node:assert/strict'
import fs from 'node:fs'
import {spawnSync} from 'node:child_process'
import {fileURLToPath} from 'node:url'
import {createHash} from 'node:crypto'
const file='docs/evidence/P6E-barrier-final-check-r2.json'
assert.ok(!fs.existsSync(file))
const hash=b=>createHash('sha256').update(b).digest('hex')
const previous=JSON.parse(fs.readFileSync('docs/evidence/P6E-barrier-final-check.json'))
const copy=JSON.parse(fs.readFileSync('docs/evidence/P6E-barrier-control-directory.json'))
const report={at:new Date().toISOString(),commands:[],controllerSource:fs.readFileSync(fileURLToPath(import.meta.url),'utf8'),runtimeFiles:{},scope:'Final code/retention checks; maintenance Dockerfile copy fix has dedicated real probe. NOT final six-role acceptance.'}
function run(executable,args,options={}){
 const r=spawnSync(executable,args,{encoding:'utf8',maxBuffer:32*1024*1024,timeout:120000,...options})
 report.commands.push({executable,args,exitCode:r.status,stdout:r.stdout,stderr:r.stderr});fs.writeFileSync(file,JSON.stringify(report,null,2)+'\n');assert.equal(r.status,0);return r.stdout.trim()
}
try{
 for(const [f,h]of Object.entries(previous.runtimeFiles)){
   const actual=hash(fs.readFileSync(f))
   if(f==='backend/maintenance.Dockerfile')assert.equal(actual,copy.fixedDockerfileSHA256)
   else assert.equal(actual,h,f)
   report.runtimeFiles[f]=actual
 }
 report.dockerfileException={file:copy.fixedDockerfile,sha256:copy.fixedDockerfileSHA256,evidence:'P6E-barrier-control-directory.json',exitCode:0,actualDirectory:'700 10001 10001'}
 for(const [f,h]of Object.entries(previous.originalSHA256.evidence))assert.equal(hash(fs.readFileSync('docs/evidence/'+f)),h)
 for(const [f,h]of Object.entries(previous.originalSHA256.markers))assert.equal(hash(fs.readFileSync(f)),h)
 report.retainedEvidence=previous.retainedEvidence;report.retainedMarkers=previous.retainedMarkers
 const names=run('git',['diff','--name-only']).split(/\r?\n/).concat(run('git',['ls-files','--others','--exclude-standard']).split(/\r?\n/))
 const scripts=[...new Set(names)].filter(f=>f.startsWith('scripts/')&&f.endsWith('.mjs'))
 const docs=[...new Set(names)].filter(f=>f.endsWith('.md'))
 run(process.execPath,['node_modules/prettier/bin/prettier.cjs','--write',...docs])
 run(process.execPath,['node_modules/prettier/bin/prettier.cjs','--check',...scripts,...docs,'compose.admin-dev.yaml','compose.admin-publish.yaml'])
 run(process.execPath,['node_modules/eslint/bin/eslint.js',...scripts,'--max-warnings','0'])
 run('git',['diff','--check'])
 const go=[...new Set(names)].filter(f=>f.endsWith('.go'))
 assert.equal(run('C:/dev/Go/go/bin/gofmt.exe',['-l',...go]),'')
 report.remote=run('git',['ls-remote','origin','refs/heads/feat/v1.1-admin-p6a','refs/heads/main'])
 assert.match(report.remote,/19c58ddadccd43cc410a15a243f2ddc7802d80e5\s+refs\/heads\/feat\/v1.1-admin-p6a/)
 assert.match(report.remote,/14f9b1fba6504b1367aad6165a0b72c37e495927\s+refs\/heads\/main/)
 report.context=run('docker',['context','show']);assert.equal(report.context,'desktop-linux')
 const quality=JSON.parse(fs.readFileSync('docs/evidence/P6E-barrier-quality.json'))
 for(const [f,h]of Object.entries(quality.inputs))assert.equal(hash(fs.readFileSync(f)),h)
 const sourceFiles=[...new Set(names)].filter(f=>/\.(mjs|go|md|ya?ml)$|Dockerfile$/.test(f))
 report.secretScan={scope:sourceFiles.length,patterns:'GitHub token prefixes; PEM/OpenSSH private-key blocks',findings:[]}
 for(const f of sourceFiles){const data=fs.readFileSync(f,'utf8');if(/gh[pousr]_[A-Za-z0-9]{30,}|github_pat_[A-Za-z0-9_]{30,}|-----BEGIN (?:OPENSSH|RSA|EC) PRIVATE KEY-----/.test(data))report.secretScan.findings.push(f)}
 assert.deepEqual(report.secretScan.findings,[])
 report.result='passed'
}catch(error){report.result='failed';report.error=error.stack;process.exitCode=1}
fs.writeFileSync(file,JSON.stringify(report,null,2)+'\n')
console.log(JSON.stringify({file,result:report.result,retainedEvidence:report.retainedEvidence,retainedMarkers:report.retainedMarkers,error:report.error}))
